type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(shape.len() == 2, "shape must have exactly two dimensions");
    let rows = shape[0] as usize;
    let cols = shape[1] as usize;
    let len = a.len();

    if len == rows {
        // Treat `a` as a column vector: broadcast each element across its row.
        let mut matrix = Vec::with_capacity(rows);
        for i in 0..rows {
            // For row i, repeat a[i] across all columns.
            matrix.push(vec![a[i]; cols]);
        }
        matrix
    } else if len == cols {
        // Treat `a` as a row vector: broadcast the entire row for each new row.
        let mut matrix = Vec::with_capacity(rows);
        for _ in 0..rows {
            matrix.push(a.clone());
        }
        matrix
    } else {
        panic!("Length of the array must equal either number of rows or number of columns");
    }
}